export interface ConnectorConfig {
  /** Pipedrive API token, typically from env var PIPEDRIVE_API_TOKEN */
  pipedriveApiToken: string;
  /** Mapping of Typeform field IDs to the expected data points */
  typeformFieldIds: {
    /** Field ID for the respondent's full name */
    name: string;
    /** Field ID for the respondent's email */
    email: string;
    /** Field ID for the company name */
    company: string;
  };
  /** Injected fetch implementation (for testing) */
  fetch?: typeof fetch;
}

/** Typeform webhook payload structure */
export interface TypeformPayload {
  event_id: string;
  event_type: string;
  form_response: {
    form_id: string;
    token: string;
    submitted_at: string;
    answers: Array<{
      type: string;
      text?: string;
      email?: string;
      field: {
        id: string;
        type: string;
      };
    }>;
  };
}

/** Result of the handle function */
export interface HandleResult {
  personId: number;
  organizationId: number;
  dealId: number;
}

/**
 * Processes a Typeform form response and creates a person, organization, and deal in Pipedrive.
 * @param payload The Typeform webhook payload
 * @param config Connector configuration including API token and field ID mapping
 * @returns IDs of the created person, organization, and deal
 */
export async function handle(payload: TypeformPayload, config: ConnectorConfig): Promise<HandleResult> {
  // Validate config
  if (!config.pipedriveApiToken) {
    throw new Error('Missing Pipedrive API token (pipedriveApiToken)');
  }
  if (!config.typeformFieldIds) {
    throw new Error('Missing Typeform field IDs configuration (typeformFieldIds)');
  }
  const { name: nameFieldId, email: emailFieldId, company: companyFieldId } = config.typeformFieldIds;

  // Extract answers from payload
  const answers = payload.form_response.answers;
  const nameAnswer = answers.find((a) => a.field.id === nameFieldId);
  const emailAnswer = answers.find((a) => a.field.id === emailFieldId);
  const companyAnswer = answers.find((a) => a.field.id === companyFieldId);

  if (!nameAnswer || !nameAnswer.text) {
    throw new Error('Missing name in Typeform response');
  }
  if (!emailAnswer || !emailAnswer.email) {
    throw new Error('Missing email in Typeform response');
  }
  if (!companyAnswer || !companyAnswer.text) {
    throw new Error('Missing company in Typeform response');
  }

  const name = nameAnswer.text;
  const email = emailAnswer.email;
  const company = companyAnswer.text;

  const fetchImpl = config.fetch ?? globalThis.fetch;
  const apiToken = config.pipedriveApiToken;

  // Helper to make authenticated requests to Pipedrive
  async function pipedriveRequest(url: string, method: string, body: unknown): Promise<{ data: Record<string, unknown> }> {
    const fullUrl = `${url}?api_token=${encodeURIComponent(apiToken)}`;
    const response = await fetchImpl(fullUrl, {
      method,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    if (!response.ok) {
      throw new Error(`Pipedrive API error: ${response.status} ${response.statusText} for ${method} ${url}`);
    }
    return response.json();
  }

  // 1. Create person
  const personResponse = await pipedriveRequest(
    'https://api.pipedrive.com/v1/persons',
    'POST',
    { name, email }
  );
  const personId = personResponse.data.id as number;

  // 2. Create organization
  const orgResponse = await pipedriveRequest(
    'https://api.pipedrive.com/v1/organizations',
    'POST',
    { name: company }
  );
  const organizationId = orgResponse.data.id as number;

  // 3. Update person with organization_id
  await pipedriveRequest(
    `https://api.pipedrive.com/v1/persons/${personId}`,
    'PUT',
    { organization_id: organizationId }
  );

  // 4. Create deal
  const dealTitle = `Deal for ${name}`;
  const dealResponse = await pipedriveRequest(
    'https://api.pipedrive.com/v1/deals',
    'POST',
    { title: dealTitle, person_id: personId }
  );
  const dealId = dealResponse.data.id as number;

  return { personId, organizationId, dealId };
}

