      if (req.url.includes('/persons') && req.method === 'POST') {
        return jsonResponse(
          { success: true, data: { id: 111, name: 'Test', email: [{ value: 'test@example.com', primary: true }] } },
          201
        );
      }
      if (req.url.includes('/organizations') && req.method === 'POST') {
        return jsonResponse({ success: true, data: { id: 222, name: 'Test Corp' } }, 201);
      }
      if (req.url.includes('/persons/111') && req.method === 'PUT') {
        return jsonResponse({ success: true, data: { id: 111, organization_id: 222 } }, 200);
      }
      if (req.url.includes('/deals') && req.method === 'POST') {
        return jsonResponse({ success: true, data: { id: 333, title: 'Deal for Test', person_id: 111 } }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      pipedriveApiToken: 'test-token',
      typeformFieldIds: {
        name: 'name-field',
        email: 'email-field',
        company: 'company-field',
      },
      fetch,
    };

    const payload: TypeformPayload = {
      event_id: 'evt1',
      event_type: 'form_response',
