          { type: 'email', email: 'test@example.com', field: { id: 'email-field', type: 'email' } },
          { type: 'text', text: 'Test Corp', field: { id: 'company-field', type: 'short_text' } },
        ],
      },
    };

    const result = await handle(payload, config);
    expect(result).toEqual({ personId: 111, organizationId: 222, dealId: 333 });
    expect(calls.length).toBe(4);
    expect(calls[0].json).toEqual({ name: 'Test', email: 'test@example.com' });
    expect(calls[1].json).toEqual({ name: 'Test Corp' });
    expect(calls[2].json).toEqual({ organization_id: 222 });
    expect(calls[3].json).toEqual({ title: 'Deal for Test', person_id: 111 });
